const refinedModules = new Set<ModuleKey>(["product","avatar","mechanism","beliefs","offer","landing","funnel","emails","content","final_product"]);

export function ModuleView({projectId,moduleKey,evidenceFocus,onOpenEvidence,onChanged}:{projectId:string;moduleKey:ModuleKey;evidenceFocus:string|null;onOpenEvidence:(commentId:string)=>void;onChanged:()=>void}) {
  if(moduleKey==="sources")return <SourcesWorkspace key={projectId} projectId={projectId} focusCommentId={evidenceFocus} onChanged={onChanged}/>;
  return <GeneratedModuleView key={`${projectId}:${moduleKey}`} projectId={projectId} moduleKey={moduleKey} onOpenEvidence={onOpenEvidence} onChanged={onChanged}/>;
}

function SourcesWorkspace({projectId,focusCommentId,onChanged}:{projectId:string;focusCommentId:string|null;onChanged:()=>void}){
  const [savedFocus,setSavedFocus]=useState<string|null>(null);
  return <><ResearchFocusPanel projectId={projectId} onChanged={onChanged} onSaved={setSavedFocus}/><SourcesView projectId={projectId} savedFocus={savedFocus} focusCommentId={focusCommentId} onChanged={onChanged}/></>;
}

function ResearchFocusPanel({projectId,onChanged,onSaved}:{projectId:string;onChanged:()=>void;onSaved:(focus:string)=>void}){const [reload,setReload]=useState(0);const requests=useRequestGuard(projectId);const [value,setValue]=useState(""),[saved,setSaved]=useState<string|null>(null),[saving,setSaving]=useState(false),[error,setError]=useState<string|null>(null);useEffect(()=>{const current=requests.begin();setError(null);void api.researchFocus(projectId).then(focus=>{if(!current())return;setValue(focus.value??"");setSaved(focus.value);}).catch(reason=>{if(current())setError(messageOf(reason));});},[projectId,reload]);const save=async()=>{if(value.trim().length<3)return;const current=requests.begin();setSaving(true);setError(null);try{const focus=await api.saveResearchFocus(projectId,value);if(!current())return;setValue(focus.value);setSaved(focus.value);onSaved(focus.value);onChanged();}catch(reason){if(current())setError(messageOf(reason));}finally{if(current())setSaving(false);}};return <section className="content-section"><article className="detail-card research-focus-panel"><span className="eyebrow">RESEARCH FOCUS</span><label>Foco activo de Research y Problemas<input maxLength={240} value={value} onChange={event=>setValue(event.target.value)} placeholder="Tema o problema a investigar"/></label><div className="button-row"><button type="button" className="button primary" disabled={saving||value.trim().length<3} onClick={()=>void save()}>Guardar</button>{saved&&<small>Activo: {saved}</small>}</div>{error&&<InlineError message={error} onRetry={()=>setReload(value=>value+1)}/>}</article></section>;}

function GeneratedModuleView({projectId,moduleKey,onOpenEvidence,onChanged}:{projectId:string;moduleKey:ModuleKey;onOpenEvidence:(commentId:string)=>void;onChanged:()=>void}) {
  const [results,setResults]=useState<ModuleResult[]>([]),[selectedId,setSelectedId]=useState<string|null>(null);
  const [instructions,setInstructions]=useState("");
  const [files,setFiles]=useState<GeneratedFile[]>([]);
  const [evidence,setEvidence]=useState<EvidenceSnippet[]>([]);
  const [provider,setProvider]=useState<"mock"|"openai"|"gemini"|"deepseek">("mock"),[openAiConfigured,setOpenAiConfigured]=useState<boolean|null>(null),[geminiConfigured,setGeminiConfigured]=useState<boolean|null>(null),[deepSeekConfigured,setDeepSeekConfigured]=useState<boolean|null>(null);
  const [versionProviders,setVersionProviders]=useState<Record<string,{provider:string;model:string}>>({});
  const [loading,setLoading]=useState(true),[running,setRunning]=useState(false),[error,setError]=useState<string|null>(null);
  const requests=useRequestGuard(`${projectId}:${moduleKey}`);
  const info=moduleInfo(moduleKey);
  const load=async()=>{const current=requests.begin();setLoading(true);setError(null);try{const [response,fileResponse,providerResponse,generationResponse]=await Promise.all([api.moduleResults(projectId,moduleKey),api.files(projectId),api.providerStatus(projectId),api.generations(projectId)]);if(!current())return;setResults(response.results);setFiles(fileResponse.files);setOpenAiConfigured(providerResponse.openai.configured);setGeminiConfigured(providerResponse.gemini.configured);setDeepSeekConfigured(providerResponse.deepseek.configured);setProvider(providerResponse.defaultProvider);const providers:Record<string,{provider:string;model:string}>={};for(const g of generationResponse.generations){if(g.artifactVersionId!==null)providers[g.artifactVersionId]={provider:g.provider,model:g.model};}setVersionProviders(providers);setSelectedId((current)=>response.results.some(item=>item.versionId===current)?current:response.results[0]?.versionId??null);}catch(reason){if(!current())return;if(reason instanceof ApiClientError&&reason.status===404)setResults([]);else setError(messageOf(reason));}finally{if(current())setLoading(false);}};
  useEffect(()=>{void load();},[projectId,moduleKey]);
  const run=async()=>{const current=requests.begin(),alive=requests.capture();setLoading(false);setRunning(true);setError(null);try{const result=await api.runModule(projectId,moduleKey,{provider,...((moduleKey==="research"||moduleKey==="product")&&instructions.trim()?{instructions:instructions.trim()}:{})});if(!current())return;setResults((current)=>[result,...current.filter((item)=>item.versionId!==result.versionId)]);const [fileResponse,generationResponse]=await Promise.all([api.files(projectId),api.generations(projectId)]);if(!current())return;setFiles(fileResponse.files);const providers:Record<string,{provider:string;model:string}>={};for(const g of generationResponse.generations){if(g.artifactVersionId!==null)providers[g.artifactVersionId]={provider:g.provider,model:g.model};}setVersionProviders(providers);setSelectedId(result.versionId);onChanged();}catch(reason){if(current())setError(messageOf(reason));}finally{if(alive())setRunning(false);}};
  const selected=results.find((result)=>result.versionId===selectedId)??results[0];
  useEffect(()=>{let active=true;setEvidence([]);if(!selected){setEvidence([]);return;}const ids=collectEvidenceIds(selected.outputData);void Promise.all(ids.slice(0,20).map((id)=>api.evidence(projectId,id).catch(()=>null))).then((items)=>{if(active)setEvidence(items.filter((item):item is EvidenceSnippet=>item!==null));});return()=>{active=false;};},[projectId,selected?.versionId]);
  return <section className={`content-section module-workspace${moduleKey==="research"?" research-workspace":""}`}>
    <div className={`module-toolbar${moduleKey==="research"?" research-toolbar":""}`}><div className="module-toolbar-text">{moduleKey==="research"&&<span className="eyebrow">RESEARCH WORKSPACE</span>}<p className="module-toolbar-description">{info.description}</p></div><div className="module-generation-actions"><label className="provider-control"><span>Proveedor</span><select value={provider} disabled={loading||running} onChange={(event)=>setProvider(event.target.value as "mock"|"openai"|"gemini"|"deepseek")}><option value="mock">Demo / Mock</option><option value="openai" disabled={!openAiConfigured}>OpenAI{openAiConfigured===null?" · comprobando":openAiConfigured?"":" · no configurado"}</option><option value="gemini" disabled={!geminiConfigured}>Gemini{geminiConfigured===null?" · comprobando":geminiConfigured?"":" · no configurado"}</option><option value="deepseek" disabled={!deepSeekConfigured}>DeepSeek{deepSeekConfigured===null?" · comprobando":deepSeekConfigured?"":" · no configurado"}</option></select></label><button className="button primary" disabled={loading||running||provider==="openai"&&!openAiConfigured||provider==="gemini"&&!geminiConfigured||provider==="deepseek"&&!deepSeekConfigured} onClick={()=>void run()}>{running?"Generando…":results.length?`Regenerar con ${provider==="openai"?"OpenAI":provider==="gemini"?"Gemini":provider==="deepseek"?"DeepSeek":"Demo"}`:`Generar con ${provider==="openai"?"OpenAI":provider==="gemini"?"Gemini":provider==="deepseek"?"DeepSeek":"Demo"}`}</button></div></div>
    {!loading&&selected&&["research","problems","opportunities","product"].includes(moduleKey)&&<ModuleReviewSummary moduleKey={moduleKey} selected={selected} versionCount={results.length} evidenceCount={collectEvidenceIds(selected.outputData).length}/>}
    {moduleKey==="research"&&<details className="detail-card generation-brief" open={!selected}><summary>Orientar una próxima generación</summary><label>Orientación para el próximo brief<textarea value={instructions} maxLength={4000} rows={3} onChange={event=>setInstructions(event.target.value)} placeholder="Qué quieres comprender, qué excluir y qué hipótesis contrastar"/></label><p className="form-hint">Opcional. Se combina con la descripción del proyecto y el Research Focus al generar. No modifica versiones anteriores ni ejecuta búsquedas externas. Demo no interpreta estas instrucciones con un modelo.</p></details>}
    {moduleKey==="product"&&<details className="detail-card generation-brief" open={!selected}><summary>Decisiones para una próxima generación</summary><label>Decisiones y límites del producto<textarea value={instructions} maxLength={4000} rows={3} onChange={event=>setInstructions(event.target.value)} placeholder="Formato y recursos disponibles, alcance, servicios que realmente puedes ofrecer y exclusiones"/></label><p className="form-hint">Opcional: decisiones explícitas para la próxima generación. No autorices garantías o servicios que no puedes cumplir. Demo usa contenido de prueba y no interpreta estas instrucciones con un modelo.</p></details>}
    {error&&<InlineError message={error} onRetry={()=>void load()}/>} 
    {!loading&&selected?.freshness==="stale"&&!["research","problems","opportunities","product"].includes(moduleKey)&&<div className="detail-card" role="status"><span className="status-pill stale">Versión obsoleta · v{selected.versionNumber}</span><p>Las fuentes o las dependencias cambiaron desde que se generó este resultado. Actualiza primero los módulos anteriores y regenera esta versión antes de continuar.</p></div>}
    {loading?<LoadingCards/>:!selected?(moduleKey==="landing"?<LandingPreparation/>:moduleKey==="offer"?<OfferPreparation/>:moduleKey==="avatar"||moduleKey==="mechanism"?<StrategyEmptyState moduleKey={moduleKey}/>:<DependencyEmpty moduleKey={moduleKey} onRun={()=>void run()} running={running}/>):refinedModules.has(moduleKey)?<RefinedModuleOutput evidence={evidence} key={selected.versionId} projectId={projectId} moduleKey={moduleKey} selected={selected} versions={results} files={files} onSelectVersion={setSelectedId} onRegenerate={run} onVersionCreated={(version)=>{if(!requests.capture()())return;if(moduleKey==="product"||moduleKey==="avatar"||moduleKey==="mechanism"||moduleKey==="beliefs"||moduleKey==="offer"||moduleKey==="landing"){void load().then(()=>{if(requests.capture()())setSelectedId(version.versionId);});onChanged();return;}requests.invalidate();setResults((current)=>[version,...current.filter((item)=>item.versionId!==version.versionId)]);setSelectedId(version.versionId);onChanged();}}/>:moduleKey==="problems"?<ProblemsWorkspace selected={selected} results={results} versionProviders={versionProviders} onSelectVersion={setSelectedId} onOpenEvidence={onOpenEvidence}/>:moduleKey==="research"?<ResearchResultWorkspace selected={selected} results={results} versionProviders={versionProviders} evidence={evidence} onSelectVersion={setSelectedId}/>:moduleKey==="opportunities"?<OpportunityWorkspace projectId={projectId} selected={selected} results={results} versionProviders={versionProviders} onSelectVersion={setSelectedId} onVersionCreated={version=>{void load().then(()=>{if(requests.capture()())setSelectedId(version.versionId);});onChanged();}}/>:<div className="module-workspace-body">
      <article className="result-document"><div className="result-heading"><div><span className="eyebrow">RESULTADO</span><h2>{info.label} · v{selected.versionNumber}</h2></div><div className="badge-row"><span className={`status-pill ${selected.freshness}`}>{selected.freshness}</span><span className="status-pill">{selected.status}</span></div></div><StructuredOutput value={selected.outputData}/></article>
      {results.length>1&&<div className="version-strip"><span className="eyebrow">VERSIONES</span><div className="version-strip-list">{results.map((result)=><button key={result.versionId} className={selected.versionId===result.versionId?"active":""} onClick={()=>setSelectedId(result.versionId)} title={`v${result.versionNumber} · ${providerLabel(versionProviders[result.versionId])} · ${new Date(result.createdAt).toLocaleString("es")}`}><span className={`version-dot ${providerDotClass(versionProviders[result.versionId])}`}/>v{result.versionNumber}</button>)}</div></div>}
    </div>}
    {files.some((file)=>file.artifactVersionId===selected?.versionId)&&<article className="detail-card jobs-panel"><span className="eyebrow">ARCHIVOS GENERADOS</span><div className="history-list">{files.filter((file)=>file.artifactVersionId===selected?.versionId).map((file)=><div key={file.id}><div><strong>{humanize(file.fileRole)}</strong><a className="button secondary" href={file.downloadUrl}>Descargar .{file.format}</a></div><small>{file.bytes.toLocaleString("es")} bytes · SHA-256 {file.checksum.slice(0,12)}…</small></div>)}</div></article>}
    {evidence.length>0&&<article className="detail-card jobs-panel"><span className="eyebrow">EVIDENCIA VINCULADA</span><div className="comment-list">{evidence.map((item)=><article key={item.id}><header><strong>{item.author}</strong><span className="status-pill fresh">{item.provenance}</span></header><p>“{item.quoteText}”</p><footer>{item.sourceTitle} · {item.id}<br/><button className="button secondary" onClick={()=>onOpenEvidence(item.commentId)}>Abrir comentario original</button></footer></article>)}</div></article>}
  </section>;
}

export function ResearchResultWorkspace({selected,results,versionProviders,evidence,onSelectVersion}:{selected:ModuleResult;results:ModuleResult[];versionProviders:Record<string,{provider:string;model:string}>;evidence:EvidenceSnippet[];onSelectVersion:(versionId:string)=>void}) {
  const generation=versionProviders[selected.versionId];
  return <div className="research-layout">
    <article className="research-document">
      <header className="research-document-header"><div><span className="eyebrow">{selected.status==="superseded"||selected.status==="archived"?"VERSIÓN HISTÓRICA":"DOCUMENTO SELECCIONADO"}</span><h2>Brief de investigación</h2><div className="research-document-meta"><span><CalendarDays size={13}/>{new Date(selected.createdAt).toLocaleString("es")}</span><span><span className={`version-dot ${providerDotClass(generation)}`}/>{providerLabel(generation)}{generation?.model?` · ${generation.model}`:""}</span></div></div><div className="badge-row"><span className={`status-pill ${selected.freshness}`}>{reviewStateLabel(selected.freshness)}</span><span className="status-pill">{reviewStateLabel(selected.status)}</span></div></header>
      <section className="research-context-note"><FileText size={15}/><p>Este brief orienta qué investigar y qué buscar en Fuentes. Las hipótesis requieren contraste; una cita vinculada no prueba causalidad, eficacia ni demanda de mercado. Research usa una muestra de hasta 20 evidencias locales elegibles, no un estudio representativo del mercado.</p></section>
      <StructuredOutput value={selected.outputData} evidence={evidence}/>
    </article>
    <aside className="research-inspector" aria-label="Contexto del documento">
      <section className="research-context-section"><div className="research-context-heading"><Layers3 size={15}/><span>Versiones</span><small>{results.length}</small></div><div className="research-version-list">{results.map((result)=>{const itemProvider=versionProviders[result.versionId];return <button key={result.versionId} className={selected.versionId===result.versionId?"active":""} onClick={()=>onSelectVersion(result.versionId)}><span className={`version-dot ${providerDotClass(itemProvider)}`}/><span><strong>Versión {result.versionNumber}</strong><small>{providerLabel(itemProvider)} · {new Date(result.createdAt).toLocaleDateString("es")}</small></span>{selected.versionId===result.versionId&&<CheckCircle2 size={14}/>}</button>;})}</div></section>
      <section className="research-context-section"><div className="research-context-heading"><ShieldCheck size={15}/><span>Procedencia</span></div><dl className="research-provenance"><div><dt>Proveedor</dt><dd>{providerLabel(generation)}</dd></div><div><dt>Modelo</dt><dd>{generation?.model??"No registrado"}</dd></div><div><dt>Evidencia vinculada</dt><dd>{evidence.length} referencias disponibles</dd></div></dl><div className="research-legend"><span><i className="evidence-backed"/>Con evidencia</span><span><i className="ai-inference"/>Inferencia IA</span></div></section>
      <section className="research-context-note"><FileText size={15}/><p>Los hallazgos conservan su clasificación de procedencia y las referencias disponibles en esta versión.</p></section>
    </aside>
  </div>;
}

export function ProblemsWorkspace({selected,results,versionProviders,onSelectVersion,onOpenEvidence}:{selected:ModuleResult;results:ModuleResult[];versionProviders:Record<string,{provider:string;model:string}>;onSelectVersion:(id:string)=>void;onOpenEvidence:(id:string)=>void}){
  const generation=versionProviders[selected.versionId];
  return <div className="module-workspace-body"><header className="detail-card result-heading"><div><span className="eyebrow">{selected.status==="superseded"||selected.status==="archived"?"VERSIÓN HISTÓRICA":"INTERPRETACIÓN SELECCIONADA"}</span><h2>Problemas · v{selected.versionNumber}</h2><p>{providerLabel(generation)} · {new Date(selected.createdAt).toLocaleString("es")}</p></div><div className="badge-row"><span className={`status-pill ${selected.freshness}`}>{reviewStateLabel(selected.freshness)}</span><span className="status-pill">{reviewStateLabel(selected.status)}</span></div></header><p className="form-hint">Los controles evalúan soporte, cohesión, precisión y foco dentro del corpus. Un problema admitido no equivale a demanda comercial validada. Revisa las citas y los rechazos antes de priorizar Oportunidades.</p><nav className="version-strip" aria-label="Versiones de Problemas"><span className="eyebrow">VERSIONES</span><div className="version-strip-list">{results.map(result=><button type="button" key={result.versionId} className={selected.versionId===result.versionId?"active":""} aria-pressed={selected.versionId===result.versionId} onClick={()=>onSelectVersion(result.versionId)}>Versión {result.versionNumber}</button>)}</div></nav><ProblemQualityOutput value={selected.outputData} onOpenEvidence={onOpenEvidence}/></div>;
}

export function ProblemQualityOutput({value,onOpenEvidence}:{value:unknown;onOpenEvidence:(commentId:string)=>void}){
  if(!isRecord(value)||!Array.isArray(value.items))return <StructuredOutput value={value}/>;
  const metrics=isRecord(value.analysisMetrics)?value.analysisMetrics:null;
  const audit=isRecord(value.analysisAudit)?value.analysisAudit:null;
  const postMergeClusters=audit&&Array.isArray(audit.postMergeClusters)?audit.postMergeClusters.filter(isRecord):null;
  const preMergeRejected=audit&&Array.isArray(audit.preMergeRejectedCandidates)?audit.preMergeRejectedCandidates.filter(isRecord):null;
  const allAuditClusters=postMergeClusters?[...postMergeClusters,...(preMergeRejected??[])]:null;
  const items=value.items.filter(isRecord);
  const metric=(name:string)=>metrics&&typeof metrics[name]==="number"?String(metrics[name]):"No disponible";
  const batchMetric=metrics&&typeof metrics.batchesSentToProvider==="number"?String(metrics.batchesSentToProvider):metric("batchesSentToGemini");
  const DECISION_LABELS:Record<string,string>={"VALIDATED":"VALIDADO","REJECTED_LOW_COHESION":"BAJA COHESIÓN","REJECTED_LOW_PRECISION":"BAJA PRECISIÓN","REJECTED_NO_SUPPORT":"SIN SOPORTE","REJECTED_OUT_OF_SCOPE":"FUERA DE FOCO","REJECTED_MISCELLANEOUS":"MISCELÁNEO","REJECTED_LOW_INTERNAL_COHERENCE":"INCOHERENCIA INTERNA"};
  const DECISION_CLASS:Record<string,string>={"VALIDATED":"fresh","REJECTED_LOW_COHESION":"stale","REJECTED_LOW_PRECISION":"stale","REJECTED_NO_SUPPORT":"stale","REJECTED_OUT_OF_SCOPE":"stale","REJECTED_MISCELLANEOUS":"stale","REJECTED_LOW_INTERNAL_COHERENCE":"stale"};
  const groups:ReadonlyArray<readonly [string,ReadonlyArray<readonly [string,string]>]>=metrics?[
    ["CORPUS",[["RAW",metric("rawComments")],["Elegibles",metric("analysisEligibleComments")],["Procesados semánticamente",metric("commentsSelectedForSemanticAnalysis")],["Coverage",`${metric("corpusCoverage")}%`]]],
    ["PIPELINE",[["Batches procesados",batchMetric],["Comentarios por batch",metric("commentsPerBatch")],["Candidatos semánticos",metric("candidateInsights")],["Clusters después del merge",metric("candidateClusters")],["Problemas validados",metric("validatedProblems")]]],
    ["QUALITY GATE",[["Clusters divididos o rechazados por baja cohesión",metric("clustersSplitForLowCohesion")],["Clusters rechazados por baja precisión",metric("clustersRejectedForLowPrecision")],["Sin soporte DIRECT/INFERRED",metric("clustersRejectedNoSupport")],["Fuera de foco",metric("clustersRejectedOutOfScope")],["Misceláneos pre-merge",metric("clustersRejectedMiscellaneous")],["Clusters rechazados por incoherencia interna",metric("clustersRejectedInternalCoherence")],["Relaciones de evidencia rechazadas por ser solo instrucción",metric("evidenceRejectedInstructionOnly")],["Relaciones de evidencia rechazadas por ser solo contexto",metric("evidenceRejectedContextOnly")],["Relaciones positivas sin problema excluidas",metric("positiveOnlyCommentsExcluded")]]],
    ["RESULTADOS",[["SIGNAL",metric("signals")],["EMERGING",metric("emerging")],["PATTERN",metric("patterns")],["STRONG PATTERN",metric("strongPatterns")]]],
  ]:[];
  return <article className="detail-card result-panel"><span className="eyebrow">PROBLEMAS VALIDADOS</span>{typeof value.researchFocus==="string"&&<p className="muted-copy">Foco: {value.researchFocus}</p>}<details className="analysis-details"><summary>Detalles del análisis</summary><p className="form-hint">Las métricas corresponden al corpus de esta versión al generarse; no son el recuento actual de Fuentes.</p>{metrics?<><div className="metric-strip"><div><strong>{metric("rawComments")}</strong><span>RAW</span></div><div><strong>{metric("analysisEligibleComments")}</strong><span>elegibles</span></div><div><strong>{metric("commentsSelectedForSemanticAnalysis")}</strong><span>procesados</span></div><div><strong>{metric("corpusCoverage")}%</strong><span>coverage</span></div></div><div className="structured-output">{groups.map(([heading,fields])=><section className="output-section" key={heading}><h3>{heading}</h3>{fields.map(([label,amount])=><div className="output-field" key={label}><span>{label}</span><strong>{amount}</strong></div>)}</section>)}</div></>:<p className="muted-copy">Esta versión se generó antes de que se registraran métricas detalladas del pipeline.</p>}{allAuditClusters?<><h3>Clusters auditados</h3><div className="cluster-audit-list">{allAuditClusters.map((cluster,index)=>{const decision=String(cluster.finalDecision??"");const label=DECISION_LABELS[decision]??decision;const cls=DECISION_CLASS[decision]??"stale";return <details key={String(cluster.clusterId??index)} className="cluster-audit-row"><summary><span className={`status-pill ${cls}`}>{label}</span> <strong>{String(cluster.canonicalProblem??"")}</strong> <small>Cohesión: {cluster.cohesionScore!=null?String(cluster.cohesionScore):"-"} | Precisión: {cluster.evidencePrecisionScore!=null?String(cluster.evidencePrecisionScore):"-"} | Relevancia: {String(cluster.researchRelevanceScore??"-")} | Evidencias candidatas: {String(cluster.candidateEvidenceCount??0)} | Encontradas: {String(cluster.evidenceCount??0)}</small></summary><div className="cluster-audit-detail">{typeof cluster.unresolvedEvidenceCount==="number"&&cluster.unresolvedEvidenceCount>0&&<div className="output-field"><span>IDs no resueltos</span><strong>{(Array.isArray(cluster.unresolvedEvidenceIds)?cluster.unresolvedEvidenceIds:[]).join(", ")}</strong></div>}<div className="output-field"><span>Categoría</span><strong>{String(cluster.category??"")}</strong></div><div className="output-field"><span>Autores</span><strong>{String(cluster.uniqueAuthors??0)}</strong></div><div className="output-field"><span>Fuentes</span><strong>{String(cluster.uniqueSources??0)}</strong></div><div className="output-field"><span>Hilos</span><strong>{String(cluster.uniqueThreads??0)}</strong></div><div className="output-field"><span>Directas</span><strong>{String(cluster.directEvidenceCount??0)}</strong></div><div className="output-field"><span>Inferidas</span><strong>{String(cluster.inferredEvidenceCount??0)}</strong></div><div className="output-field"><span>Nivel relevancia</span><strong>{String(cluster.researchRelevanceLevel??"")}</strong></div>{cluster.strengthScore!=null&&<div className="output-field"><span>Strength</span><strong>{String(cluster.strengthScore)}</strong></div>}{typeof cluster.strengthLevel==="string"&&<div className="output-field"><span>Nivel</span><strong>{String(cluster.strengthLevel)}</strong></div>}{typeof cluster.internalComponentCount==="number"&&<div className="output-field"><span>Componentes internos</span><strong>{String(cluster.internalComponentCount)}</strong></div>}{typeof cluster.largestInternalComponentSize==="number"&&<div className="output-field"><span>Componente interno mayor</span><strong>{String(cluster.largestInternalComponentSize)}</strong></div>}{typeof cluster.internalConnected==="boolean"&&<div className="output-field"><span>Conexión interna</span><strong>{cluster.internalConnected?"Sí":"No"}</strong></div>}{Array.isArray(cluster.evidenceQuality)?<details className="quality-breakdown"><summary>Cómo se calculó</summary><div className="output-field"><span>CLAIM AUDITADO</span><strong>{String(cluster.claim??"")}</strong></div><div className="structured-output">{cluster.evidenceQuality.filter(isRecord).map((detail,detailIndex)=><section className="output-section" key={String(detail.evidenceId??detailIndex)}><h3>Evidencia {detailIndex+1}</h3><div className="output-field"><span>Clasificación</span><strong>{String(detail.supportType??"")}</strong></div><div className="output-field"><span>Conceptos compartidos</span><strong>{Array.isArray(detail.semanticConceptsShared)?detail.semanticConceptsShared.join(", ")||"—":"—"}</strong></div><div className="output-field"><span>Regla aplicada</span><strong>{String(detail.classifierRule??"")}</strong></div><div className="output-field"><span>Aporte a cohesión</span><strong>{String(detail.cohesionContribution??0)}</strong></div><div className="output-field"><span>En denominador</span><strong>{detail.includedInCohesionDenominator?"Sí":"No"}</strong></div></section>)}</div></details>:<p className="muted-copy">Esta versión se generó antes de que se registrara el desglose semántico de calidad.</p>}<div className="output-field rejection-reason"><span>Decisión</span><strong>{label}</strong></div><div className="output-field rejection-reason"><span>Motivo</span><strong>{String(cluster.rejectionReason??"")}</strong></div></div></details>;})}</div></>:<p className="muted-copy">Esta versión se generó antes de que se registrara el audit trail de clusters.</p>}</details>{items.length===0&&<div className="compact-empty"><strong>No hay problemas que hayan superado los controles en esta versión.</strong><p>Esto no demuestra que el mercado carezca de problemas. Revisa el foco, las fuentes incluidas y los motivos de rechazo en Detalles del análisis antes de ampliar el corpus o regenerar.</p></div>}<div className="problem-quality-list">{items.map((item,index)=>{const evidence=Array.isArray(item.evidence)?item.evidence:[];const strength=typeof item.problemStrengthScore==="number"?item.problemStrengthScore:null;return <section key={String(item.id??index)} className={`problem-quality-card strength-${String(item.strengthLevel??"signal").toLowerCase()}`}><div className="badge-row"><span className={`status-pill ${String(item.strengthLevel??"signal").toLowerCase()}`}>{({SIGNAL:"Señal",EMERGING:"Emergente",PATTERN:"Patrón",STRONG_PATTERN:"Patrón sólido"}[String(item.strengthLevel)]??"Sin nivel registrado")}</span><span className="signal-strength"><strong>{strength===null?"Sin puntuación registrada":`Solidez ${strength}/100`}</strong>{strength!==null&&<StrengthMeter value={strength}/>}</span></div><h3>{String(item.name??"Problema")}</h3><p>{String(item.summary??"")}</p><small>{String(item.evidenceCount??"—")} evidencias · {String(item.uniqueAuthors??"—")} autores · {String(item.uniqueSources??"—")} fuentes<br/>Directas: {String(item.directEvidenceCount??"—")} · Inferidas: {String(item.inferredEvidenceCount??"—")} · Precisión: {String(item.evidencePrecisionScore??"—")}%</small>{evidence.slice(0,3).map((entry,quoteIndex)=>isRecord(entry)?<blockquote key={quoteIndex}><MessageSquareText size={15}/><div><p>“{String(entry.quote??"")}”</p><footer>{String(entry.author??"")} · {String(entry.sourceTitle??"")} · {String(entry.supportType??"")}</footer></div></blockquote>:null)}{evidence.map((entry,index)=>isRecord(entry)&&typeof entry.commentId==="string"?<button key={String(entry.evidenceId??index)} className="button secondary" onClick={()=>onOpenEvidence(String(entry.commentId))}>Ver evidencia {index+1}</button>:null)}</section>;})}</div></article>;
}
const PROVIDER_STATE_CLASS:Record<MarketResearchProviderState,string>={available:"fresh",not_configured:"stale",temporary_error:"stale"};

function ProviderTile({provider,status,selected,running,onToggle}:{provider:MarketResearchStatus["providers"][number];status:MarketResearchStatus|null;selected:boolean;running:boolean;onToggle:()=>void}) {
  const available=provider.state==="available";
  const content=<><span className="provider-tile-mark">{marketResearchProviderLabel(provider.provider).slice(0,2).toUpperCase()}</span><div className="provider-tile-copy"><strong>{marketResearchProviderLabel(provider.provider)}</strong><small>{provider.provider==="youtube"&&status?`${status.budgets.youtubeTargetVideos} videos · ${status.budgets.youtubeTargetComments} comentarios`:`Budget máximo · ${provider.budget}`}</small></div><StatusBadge tone={available?"success":"warning"}>{marketResearchProviderStateLabel(provider.state)}</StatusBadge>{available&&<span className="provider-selection-state"><CheckCircle2 size={13}/>{selected?"Seleccionado":"Seleccionar"}</span>}</>;
  return available?<label className={`provider-tile ${PROVIDER_STATE_CLASS[provider.state]}${selected?" selected":""}`}><input className="provider-checkbox" type="checkbox" disabled={running} checked={selected} onChange={onToggle}/>{content}</label>:<div className={`provider-tile ${PROVIDER_STATE_CLASS[provider.state]} disabled`} aria-disabled="true">{content}</div>;
}

function AutomaticSourcesPanel({projectId,savedFocus}:{projectId:string;savedFocus:string|null}) {
  const [reload,setReload]=useState(0);
  const [status,setStatus]=useState<MarketResearchStatus|null>(null);
  const [topic,setTopic]=useState(""),[selected,setSelected]=useState<MarketResearchProvider[]>([]);
  const [run,setRun]=useState<MarketResearchRun|null>(null),[history,setHistory]=useState<readonly MarketResearchRun[]>([]),[latestRunId,setLatestRunId]=useState<string|null>(null),[running,setRunning]=useState(false),[phase,setPhase]=useState(0);
  const [error,setError]=useState<string|null>(null),[openFindingId,setOpenFindingId]=useState<string|null>(null);
  const [topicEdited,setTopicEdited]=useState(false),[evidenceFilter,setEvidenceFilter]=useState<MarketResearchEvidenceFilter>("all");

  // Research Focus is the canonical topic default; a project switch clears the
  // previous project's topic first so a stale focus can never be shown.
  useEffect(()=>{let active=true;setStatus(null);setRun(null);setHistory([]);setLatestRunId(null);setError(null);setTopic("");setTopicEdited(false);setEvidenceFilter("all");void Promise.all([api.marketResearchStatus(projectId),api.latestMarketResearch(projectId),api.marketResearchHistory(projectId),api.researchFocus(projectId).catch(()=>({value:null,source:null}))]).then(([next,latest,recent,focus])=>{if(!active)return;setStatus(next);setSelected(next.providers.filter(provider=>provider.state==="available").map(provider=>provider.provider));setRun(latest);setLatestRunId(latest?.runId??null);setHistory(recent.runs);setTopic(current=>researchTopicDefault(focus.value,current,false));}).catch(reason=>{if(active)setError(messageOf(reason));});return()=>{active=false;};},[projectId,reload]);
  useEffect(()=>{if(savedFocus!==null)setTopic(current=>researchTopicDefault(savedFocus,current,topicEdited));},[savedFocus]);
  // Bounded, non-reasoning progress: phases advance to the last step and stop.
  useEffect(()=>{if(!running){setPhase(0);return;}const timer=window.setInterval(()=>setPhase(current=>Math.min(current+1,MARKET_RESEARCH_PROGRESS_PHASES.length-1)),1500);return()=>window.clearInterval(timer);},[running]);

  const available=status?.providers.filter(provider=>provider.state==="available")??[];
  const canRun=!running&&topic.trim().length>=3&&selected.length>0;
  const investigate=async()=>{
    setRunning(true);setError(null);setOpenFindingId(null);
    try{
      const focus=await api.researchFocus(projectId);
      const submittedTopic=researchTopicDefault(focus.value,topic,topicEdited).trim();
      setTopic(submittedTopic);
      const next=await api.runMarketResearch(projectId,{topic:submittedTopic,providers:selected});setRun(next);setLatestRunId(next.runId);setHistory((await api.marketResearchHistory(projectId)).runs);}
    catch(reason){setError(messageOf(reason));}
    finally{setRunning(false);}
  };
  const summary=run?summarizeMarketResearchRun(run):null;
  const groups=run?groupMarketResearchFindings(run):[];
  // Evidence comes only from the persisted run; no request is issued to browse it.
  const evidence=useMemo(()=>run?marketResearchSignalEvidence(run):[],[run]);
  const evidenceFilters=useMemo(()=>run?marketResearchEvidenceFilters(run):[],[run]);
  const filteredEvidence=useMemo(()=>filterMarketResearchSignalEvidence(evidence,evidenceFilter),[evidence,evidenceFilter]);

  return <article className="detail-card jobs-panel market-research-panel">
    <span className="eyebrow">FUENTES AUTOMÁTICAS</span>
    <p className="muted-copy">Un solo tema consulta los proveedores configurados en el servidor con límites fijos por ejecución. Las claves nunca salen del backend.</p>
    <div className="provider-tile-grid">{(status?.providers??[]).map(provider=><ProviderTile key={provider.provider} provider={provider} status={status} selected={selected.includes(provider.provider)} running={running} onToggle={()=>setSelected(current=>current.includes(provider.provider)?current.filter(item=>item!==provider.provider):[...current,provider.provider])}/>)}</div>
    <label>Tema a investigar<input value={topic} disabled={running||status===null} onChange={event=>{setTopicEdited(true);setTopic(event.target.value);}} placeholder="organización de fotografías digitales"/></label>
    <div className="button-row"><button type="button" className="button primary" disabled={!canRun} onClick={()=>void investigate()}>{running?"Investigando…":"Investigar mercado"}</button>{status&&<small>Análisis: {marketResearchAnalyzerLabel(status.analyzers.primary.analyzer)} · {status.analyzers.primary.model} · {marketResearchProviderStateLabel(status.analyzers.primary.state)} · respaldo {marketResearchAnalyzerLabel(status.analyzers.fallback.analyzer)} · {marketResearchProviderStateLabel(status.analyzers.fallback.state)}</small>}</div>
    {status&&available.length===0&&<p className="form-hint">Ningún proveedor automático está configurado. Puedes importar Demo o texto manual sin APIs.</p>}
    {running&&<p className="form-hint" role="status">{MARKET_RESEARCH_PROGRESS_PHASES[phase]}</p>}
    {error&&<InlineError message={error} onRetry={()=>setReload(value=>value+1)}/>}
    {run&&<p className="form-hint"><strong>{run.runId===latestRunId?"Última investigación guardada":"Investigación guardada"}</strong> · {new Date(run.completedAt).toLocaleString("es")} · {run.topic}</p>}
    {history.length>0&&<details className="analysis-details"><summary>Investigaciones anteriores ({history.length})</summary><div className="history-list">{history.map(item=><button type="button" className={run?.runId===item.runId?"active":""} key={item.runId} onClick={()=>{setRun(item);setOpenFindingId(null);}}><strong>{item.topic}</strong><small>{new Date(item.completedAt).toLocaleString("es")} · {marketResearchAnalyzerLabel(item.analysis.analyzer??"deepseek")} · {item.metrics.uniqueSignals} señales</small></button>)}</div></details>}
    {run&&summary&&<div className="market-research-result"><p className="form-hint">Estas señales pertenecen a esta investigación guardada; no se añaden automáticamente al conjunto local que usa Problemas. Una cita puede proceder de una web comercial o de un comentario: no implica demanda validada ni demuestra causalidad.</p>
      <div className="metric-strip"><div><strong>{summary.totalFound}</strong><span>señales</span></div><div><strong>{summary.valid}</strong><span>válidas</span></div><div><strong>{summary.unique}</strong><span>únicas</span></div><div><strong>{summary.analyzed}</strong><span>analizadas</span></div></div>
      <div className="structured-output">
        <section className="output-section"><h3>FUENTES</h3>{run.providers.map(report=><div className="output-field" key={report.provider}><span>{marketResearchProviderLabel(report.provider)}</span><strong>{report.failure!==null?`${marketResearchProviderStateLabel(report.state)} · ${report.failure}`:report.state==="not_configured"?marketResearchProviderStateLabel(report.state):`${report.unique} señales`}</strong></div>)}</section>
        <section className="output-section"><h3>ANÁLISIS</h3><div className="output-field"><span>Motor</span><strong>{summary.analysisLabel}{run.analysis.model===null?"":` · ${run.analysis.model}`}</strong></div><div className="output-field"><span>Respaldo usado</span><strong>{run.analysis.fallbackUsed?"Sí":"No"}</strong></div>{run.analysis.primaryFailure!==null&&<div className="output-field"><span>Fallo del primario</span><strong>{run.analysis.primaryFailure}</strong></div>}<div className="output-field"><span>Hallazgos</span><strong>{summary.findingCount}</strong></div></section>
      </div>
      <details className="analysis-details"><summary>Detalles técnicos</summary><div className="structured-output">
        <section className="output-section"><h3>SEÑALES POR PROVEEDOR</h3>{run.providers.map(report=><div className="output-field" key={report.provider}><span>{marketResearchProviderLabel(report.provider)}</span><strong>{report.failure!==null?`${marketResearchProviderStateLabel(report.state)} · ${report.failure}`:report.state==="not_configured"?marketResearchProviderStateLabel(report.state):`${report.unique} señales`}</strong></div>)}</section>
        {run.providers.find(report=>report.provider==="youtube")?.youtube&&<section className="output-section"><h3>YOUTUBE · ADQUISICIÓN</h3>{(()=>{const youtube=run.providers.find(report=>report.provider==="youtube")!.youtube!;return <><div className="output-field"><span>Videos</span><strong>{youtube.videosDiscovered} descubiertos · {youtube.videosSelected} seleccionados · {youtube.distinctVideosRepresented} representados · {youtube.distinctChannelsRepresented} canales</strong></div><div className="output-field"><span>Comentarios</span><strong>{youtube.commentsFetched} raw · {youtube.structurallyRejected+youtube.qualityRejected} rechazados · {youtube.exactDuplicatesRemoved+youtube.nearDuplicatesRemoved} duplicados · {youtube.commentsUnique} únicos</strong></div><div className="output-field"><span>Parada de adquisición</span><strong>{youtube.stopReason}</strong></div></>;})()}</section>}
        {run.analysis.youtube&&<section className="output-section"><h3>YOUTUBE · ANÁLISIS SEMÁNTICO</h3><div className="output-field"><span>Señales y batches</span><strong>{run.analysis.youtube.analyzedSignals} señales · {run.analysis.youtube.semanticBatches} batches · {run.analysis.youtube.successfulBatches} correctos · {run.analysis.youtube.failedBatches} fallidos</strong></div><div className="output-field"><span>DeepSeek / Gemini</span><strong>{run.analysis.inputTokens??0} entrada · {run.analysis.outputTokens??0} salida · Gemini fallback {run.analysis.youtube.fallbackBatches}</strong></div><div className="output-field"><span>Evidencia citada</span><strong>{run.analysis.youtube.citedSignals} señales · {run.analysis.youtube.citedVideos} videos · {run.analysis.youtube.citedChannels} canales{run.analysis.youtube.languages.length>0?` · ${run.analysis.youtube.languages.join(", ")}`:""}</strong></div></section>}
        <section className="output-section"><h3>PRESUPUESTO</h3><div className="output-field"><span>Duplicados eliminados</span><strong>{run.metrics.duplicatesRemoved}</strong></div><div className="output-field"><span>Descartadas por presupuesto</span><strong>{run.metrics.discardedByAnalysisBudget}</strong></div><div className="output-field"><span>Profundizadas con Firecrawl</span><strong>{run.metrics.deepenedSignals}</strong></div><div className="output-field"><span>Claims sin evidencia descartados</span><strong>{run.analysis.rejectedClaims}</strong></div><div className="output-field"><span>Duración</span><strong>{Math.round(run.durationMs/100)/10}s</strong></div></section>
      </div></details>
      {evidenceFilters.length>0&&<details className="analysis-details market-research-evidence"><summary>Evidencia original del Research ({run.signals.length})</summary>
        <div className="button-row">{evidenceFilters.map(filter=><button type="button" key={filter} className={evidenceFilter===filter?"button primary":"button secondary"} onClick={()=>setEvidenceFilter(filter)}>{marketResearchEvidenceFilterLabel(filter)}{filter==="all"?` (${evidence.length})`:` (${evidence.filter(item=>item.signal.provider===filter).length})`}</button>)}</div>
        {filteredEvidence.length===0?<p className="muted-copy">Esta ejecución no guardó señales de este proveedor.</p>:<div className="comment-list">{filteredEvidence.map(({signal,categories,cited})=><article key={signal.id}>
          <header><strong>{marketResearchProviderLabel(signal.provider)}</strong><div><span className="status-pill">{marketResearchSignalSourceLabel(signal.source)}</span><span className={`status-pill ${cited?"fresh":"stale"}`}>{cited?"Citada en hallazgo":"Capturada"}</span><span className="status-pill">{signal.id}</span></div></header>
          <p>“{signal.text}”</p>
          {cited&&<small>Hallazgos: {categories.map(marketResearchFindingCategoryLabel).join(" · ")}</small>}
          <footer>{new Date(signal.capturedAt).toLocaleString("es")}{signal.deepened?" · profundizada con Firecrawl":""}{signal.url!==null&&<><br/><a href={signal.url} target="_blank" rel="noreferrer">Abrir fuente ↗</a></>}</footer>
        </article>)}</div>}
      </details>}
      {groups.length===0?<p className="muted-copy">El análisis no devolvió hallazgos respaldados por las señales recuperadas.</p>:groups.map(([category,findings])=><section className="output-section" key={category}><h3>{marketResearchFindingCategoryLabel(category)}</h3>{findings.map(finding=>{
        const evidence=marketResearchFindingEvidence(run,finding);
        return <div className="output-item" key={finding.id}>
          <p className="field-value">{finding.statement}</p>
          {finding.customerLanguage!==null&&<blockquote>“{finding.customerLanguage}”</blockquote>}
          <small>{finding.evidenceStrength===undefined?marketResearchConfidenceLabel(finding.confidence):marketResearchEvidenceStrengthLabel(finding.evidenceStrength)} · {finding.supportingSignals} señales{finding.distinctVideos===undefined?"":` · ${finding.distinctVideos} videos`}{finding.distinctChannels===undefined?"":` · ${finding.distinctChannels} canales`}{finding.languages===undefined||finding.languages.length===0?"":` · ${finding.languages.join(", ")}`} · {finding.independentProviders} proveedores · {finding.domainDiversity} dominios · {finding.recentSignals} recientes{finding.contradictingSignals>0?` · ${finding.contradictingSignals} señales también en riesgos`:""}</small>
          <button type="button" className="button secondary" onClick={()=>setOpenFindingId(current=>current===finding.id?null:finding.id)}>{openFindingId===finding.id?"Ocultar evidencia":`Ver evidencia (${evidence.length})`}</button>
          {openFindingId===finding.id&&<div className="comment-list">{evidence.map(signal=><article key={signal.id}><header><strong>{marketResearchProviderLabel(signal.provider)}</strong><span className="status-pill fresh">{signal.id}</span></header><p>“{signal.text}”</p><footer>{new Date(signal.capturedAt).toLocaleString("es")}{signal.deepened?" · profundizada con Firecrawl":""}{signal.url!==null&&<><br/><a href={signal.url} target="_blank" rel="noreferrer">Abrir fuente ↗</a></>}</footer></article>)}</div>}
        </div>;
      })}</section>)}
    </div>}
  </article>;
}

const COMMENT_RENDER_BATCH=60;

function SourcesView({projectId,savedFocus,focusCommentId,onChanged}:{projectId:string;savedFocus:string|null;focusCommentId:string|null;onChanged:()=>void}) {
  const [sources,setSources]=useState<Source[]>([]),[comments,setComments]=useState<Comment[]>([]),[jobs,setJobs]=useState<Job[]>([]);
  const [query,setQuery]=useState(""),[kind,setKind]=useState<"demo"|"manual"|"youtube">("demo"),[title,setTitle]=useState(""),[content,setContent]=useState("");
  const [loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState<string|null>(null);
  const [visibleCommentCount,setVisibleCommentCount]=useState(COMMENT_RENDER_BATCH);
  const [youtubeConfigured,setYoutubeConfigured]=useState<boolean|null>(null);
  const [loaded,setLoaded]=useState(false);
  const [youtubeMode,setYoutubeMode]=useState<"search"|"url">("search"),[researchQuery,setResearchQuery]=useState(""),[researchEdited,setResearchEdited]=useState(false),[researchResults,setResearchResults]=useState<YouTubeResearchVideo[]>([]),[selectedVideos,setSelectedVideos]=useState<string[]>([]),[topLevelLimit,setTopLevelLimit]=useState(500);
  const [sourceFilter,setSourceFilter]=useState(""),[analysisFilter,setAnalysisFilter]=useState("all");
  const sourceById=useMemo(()=>new Map(sources.map(source=>[source.id,source])),[sources]);
  const isAnalyzable=(comment:Comment)=>{const source=sourceById.get(comment.sourceId);return Boolean(comment.analysisEligible&&source?.includeInAnalysis&&["ready","completed"].includes(source.status));};
  const requests=useRequestGuard(projectId);
  const load=async(clearError=true)=>{if(!requests.capture()())return;const current=requests.begin();setLoading(true);if(clearError)setError(null);try{const [bundle,allComments,jobList,youtubeStatus]=await Promise.all([api.sources(projectId),loadAllComments(projectId),api.jobs(projectId),api.youtubeStatus()]);if(!current())return;setSources(bundle.sources);setComments(allComments);setJobs(jobList.jobs.filter(job=>job.jobType==="youtube_import"));setYoutubeConfigured(youtubeStatus.configured);setLoaded(true);}catch(reason){if(current())setError(messageOf(reason));}finally{if(current())setLoading(false);}};
  useEffect(()=>{void load();},[projectId]);
  // The manual YouTube workflow shares the same canonical default topic; it is
  // only seeded while the field is pristine and never triggers a search.
  useEffect(()=>{let active=true;setResearchQuery("");setResearchEdited(false);setResearchResults([]);setSelectedVideos([]);void api.researchFocus(projectId).then(focus=>{if(active)setResearchQuery(current=>researchTopicDefault(focus.value,current,false));}).catch(()=>undefined);return()=>{active=false;};},[projectId]);
  useEffect(()=>{if(savedFocus!==null)setResearchQuery(current=>researchTopicDefault(savedFocus,current,researchEdited));},[savedFocus]);
  useEffect(()=>{if(!jobs.some((job)=>job.status==="QUEUED"||job.status==="RUNNING"))return;const timer=window.setInterval(()=>void load(false),1500);return()=>window.clearInterval(timer);},[projectId,jobs]);
  const submit=async(event:FormEvent)=>{event.preventDefault();setSaving(true);setError(null);try{const input:{sourceType:typeof kind;title?:string;url?:string;text?:string}={sourceType:kind};if(title.trim())input.title=title.trim();if(kind==="youtube")input.url=content.trim();else if(content.trim())input.text=content.trim();await api.createSource(projectId,input);setTitle("");setContent("");await load();onChanged();}catch(reason){setError(messageOf(reason));}finally{setSaving(false);}};
  const filtered=useMemo(()=>comments.filter((comment)=>(!sourceFilter||comment.sourceId===sourceFilter)&&(analysisFilter==="all"||(analysisFilter==="included"?isAnalyzable(comment):!isAnalyzable(comment)))&&`${comment.author} ${comment.text}`.toLocaleLowerCase().includes(query.toLocaleLowerCase())),[comments,query,sourceFilter,analysisFilter,sourceById]);
  const visibleComments=useMemo(()=>{
    const page=filtered.slice(0,visibleCommentCount);
    const focused=focusCommentId?filtered.find(comment=>comment.id===focusCommentId):undefined;
    return focused&&!page.some(comment=>comment.id===focused.id)?[...page,focused]:page;
  },[filtered,focusCommentId,visibleCommentCount]);
  const remainingCommentCount=Math.max(0,filtered.length-visibleComments.length);
  useEffect(()=>{setVisibleCommentCount(COMMENT_RENDER_BATCH);},[projectId,query,sourceFilter,analysisFilter]);
  useEffect(()=>{if(!focusCommentId||loading)return;document.getElementById(`comment-${focusCommentId}`)?.scrollIntoView({behavior:"smooth",block:"center"});},[focusCommentId,loading,visibleComments.length]);
  const removeSource=async(source:Source)=>{
    if(!window.confirm(`¿Eliminar la fuente “${source.title}” y sus comentarios, respuestas y evidencia derivada? Esta acción no afecta otras fuentes.`))return;
    setSaving(true);setError(null);
    try{await api.deleteSource(projectId,source.id);await load();onChanged();}
    catch(reason){setError(messageOf(reason));}
    finally{setSaving(false);}
  };
  const searchYouTube=async()=>{if(researchQuery.trim().length<2)return;setSaving(true);setError(null);try{const response=await api.youtubeSearch(projectId,researchQuery.trim());setResearchResults(response.items);setSelectedVideos([]);}catch(reason){setError(messageOf(reason));}finally{setSaving(false);}};
  const importSelected=async()=>{setSaving(true);setError(null);const current=requests.capture();try{
    const result=await queueSourceSelection(researchResults.filter(item=>selectedVideos.includes(item.videoId)&&!item.alreadyImported),video=>api.importYouTubeResearch(projectId,{videoId:video.videoId,title:video.title,topLevelLimit}));
    if(!current())return;
    setSelectedVideos(ids=>ids.filter(id=>!result.queuedIds.includes(id)));
    setResearchResults(videos=>videos.map(video=>result.queuedIds.includes(video.videoId)?{...video,alreadyImported:true}:video));
    await load();onChanged();
    if(result.error!==null)setError(`${result.queuedIds.length} importaciones encoladas. La selección restante se conserva. ${messageOf(result.error)}`);
  }catch(reason){if(current())setError(messageOf(reason));}finally{if(current())setSaving(false);}};
  const changeJob=async(job:Job,action:"cancel"|"retry")=>{setSaving(true);setError(null);try{await (action==="cancel"?api.cancelJob(projectId,job.id):api.retryJob(projectId,job.id));await load();onChanged();}catch(reason){setError(messageOf(reason));}finally{setSaving(false);}};
  const updateInclusion=async(source:Source,included:boolean)=>{setSaving(true);setError(null);try{await api.setSourceAnalysis(projectId,source.id,included);await load();onChanged();}catch(reason){setError(messageOf(reason));}finally{setSaving(false);}};
  return <section className="content-section sources-control-center"><SectionHeader eyebrow="SOURCE CONTROL CENTER" title="Fuentes y señales" description="Adquisición, evidencia local y comentarios públicos en un mismo sistema." aside={<StatusBadge tone={youtubeConfigured?"success":"warning"}>{youtubeConfigured===null?(error?"Estado de YouTube no disponible":"Comprobando YouTube"):youtubeConfigured?"YouTube disponible":"YouTube no configurado"}</StatusBadge>}/><div className="source-metrics"><MetricCard label="Fuentes" value={loaded?sources.length:"—"} detail={loaded?"Guardadas":error?"Carga no disponible":"Cargando fuentes y comentarios"} icon={Database} tone="violet"/><MetricCard label="Comentarios" value={loaded?comments.length.toLocaleString("es"):"—"} detail="Evidencia original" icon={MessageSquareText} tone="cyan"/><MetricCard label="Elegibles e incluidos" value={loaded?comments.filter(isAnalyzable).length.toLocaleString("es"):"—"} detail="Disponibles para análisis" icon={ShieldCheck} tone="green"/><MetricCard label="Jobs activos" value={loaded?jobs.filter((job)=>job.status==="RUNNING"||job.status==="QUEUED").length:"—"} detail="Procesos en curso" icon={Activity} tone="green"/></div>
    {error&&<InlineError message={error} onRetry={()=>void load()}/>} 
    <nav className="source-jump-nav" aria-label="Accesos de Fuentes"><a href="#source-saved">Fuentes guardadas</a><a href="#source-evidence">Comentarios y elegibilidad</a><a href="#source-market">Investigación de mercado</a></nav>
    <div id="source-market"><AutomaticSourcesPanel projectId={projectId} savedFocus={savedFocus}/></div>
    <div className="sources-grid" id="source-saved"><form className="detail-card source-form" onSubmit={(event)=>void submit(event)}><span className="eyebrow">AÑADIR FUENTE</span><div className="source-type-tabs">{(["demo","manual","youtube"] as const).map((type)=><button type="button" key={type} className={kind===type?"active":""} onClick={()=>{setKind(type);setContent("");}}>{type==="demo"?"Demo":type==="manual"?"Texto manual":"YouTube"}</button>)}</div><label>Título <span className="optional">Opcional</span><input value={title} onChange={(event)=>setTitle(event.target.value)} placeholder={kind==="demo"?"Corpus DEMO de organización":"Nombre reconocible"}/></label>{kind==="demo"&&<p className="form-hint">Corpus sintético de fotografías para probar el flujo sin APIs. No es evidencia real de tu mercado.</p>}{kind!=="demo"&&<label>{kind==="youtube"?"URL del video":"Texto de investigación"}<textarea required rows={6} value={content} onChange={(event)=>setContent(event.target.value)} placeholder={kind==="youtube"?"https://www.youtube.com/watch?v=…":"Pega aquí notas o investigación propia"}/></label>}<button className="button primary" disabled={saving||kind==="youtube"&&!youtubeConfigured}>{saving?"Importando…":kind==="demo"?"Importar evidencia Demo":"Añadir fuente"}</button>{kind==="youtube"&&<p className="form-hint"><span className={`status-pill ${youtubeConfigured?"fresh":"stale"}`}>{youtubeConfigured?"API configurada":"API no configurada"}</span> {youtubeConfigured?"La importación usa YouTube Data API v3.":"Añade YOUTUBE_API_KEY al entorno para habilitarla; Demo sigue disponible."}</p>}</form><article className="detail-card"><span className="eyebrow">FUENTES GUARDADAS</span>{loading?<LoadingCards/>:!loaded?<p>No se pudieron cargar las fuentes.</p>:sources.length===0?<p>No hay fuentes todavía.</p>:<div className="source-list">{sources.map((source)=><div key={source.id}><span className={`source-icon ${source.sourceType}`}>{source.sourceType[0]?.toUpperCase()}</span><div><strong>{source.title}</strong><small>{source.sourceType} · {source.status} · {new Date(source.createdAt).toLocaleDateString("es")}</small>{source.url&&<a href={source.url} target="_blank" rel="noreferrer">Abrir fuente ↗</a>}</div><label className="source-analysis-toggle"><input type="checkbox" checked={source.includeInAnalysis} disabled={saving} onChange={(event)=>void updateInclusion(source,event.target.checked)}/><span>Incluir en análisis</span></label><button type="button" className="button secondary" disabled={saving} onClick={()=>void removeSource(source)}>Eliminar fuente</button></div>)}</div>}</article></div>
    <article className="detail-card jobs-panel"><span className="eyebrow">YOUTUBE RESEARCH ENGINE</span><div className="button-row"><button type="button" className={youtubeMode==="search"?"button primary":"button secondary"} onClick={()=>setYoutubeMode("search")}>Buscar en YouTube</button><button type="button" className={youtubeMode==="url"?"button primary":"button secondary"} onClick={()=>setYoutubeMode("url")}>Añadir URL manualmente</button></div>{youtubeMode==="search"?<><label>Tema o problema a investigar<input value={researchQuery} onChange={event=>{setResearchEdited(true);setResearchQuery(event.target.value);}} placeholder="organización de fotografías digitales"/></label><p className="form-hint">Búsqueda manual de YouTube, independiente de Fuentes Automáticas. La evidencia multi-fuente del Research se consulta en “Evidencia original del Research”.</p><button className="button primary" disabled={saving||!youtubeConfigured||researchQuery.trim().length<2} onClick={()=>void searchYouTube()}>{saving?"Buscando…":"Buscar videos"}</button>{researchResults.length>0&&<><p>{selectedVideos.length} videos seleccionados · La heurística local prioriza relevancia y conversación, no solo vistas.</p><label>Límite TOP-LEVEL por video<select value={topLevelLimit} onChange={event=>setTopLevelLimit(Number(event.target.value))}>{[100,250,500,1000,2000].map(limit=><option key={limit} value={limit}>{limit}{limit===500?" · recomendado":""}</option>)}</select></label><div className="history-list">{researchResults.map(video=><div key={video.videoId}><div><label><input type="checkbox" disabled={video.alreadyImported||saving} checked={selectedVideos.includes(video.videoId)} onChange={()=>setSelectedVideos(current=>current.includes(video.videoId)?current.filter(id=>id!==video.videoId):[...current,video.videoId])}/><strong>{video.title}</strong></label><span className="status-pill fresh">{video.researchScore}/100</span></div>{video.thumbnailUrl&&<img src={video.thumbnailUrl} alt="" width="120" height="68"/>}<small>{video.channelTitle} · {video.commentCount??0} comentarios · {video.scoreExplanation}{video.alreadyImported?" · YA IMPORTADO":""}</small><a href={`https://www.youtube.com/watch?v=${video.videoId}`} target="_blank" rel="noreferrer">Abrir en YouTube ↗</a></div>)}</div><button className="button primary" disabled={saving||selectedVideos.length===0} onClick={()=>void importSelected()}>Importar seleccionados</button></>}</>:<p>Pega una URL en el formulario de Añadir fuente. <button type="button" className="button secondary" onClick={()=>{setKind("youtube");setContent("");document.querySelector(".source-form")?.scrollIntoView({behavior:"smooth",block:"center"});}}>Abrir formulario YouTube</button></p>}</article>
    {jobs.length>0&&<article className="detail-card jobs-panel"><span className="eyebrow">JOBS</span>{jobs.map((job)=><div className="job-row" key={job.id}><div><strong>{humanize(job.jobType)}</strong><small>{job.message??job.status}</small></div><div className="job-progress"><span style={{width:`${job.progress}%`}}/></div><b>{job.progress}%</b>{(job.status==="QUEUED"||job.status==="RUNNING")&&<button className="button secondary" disabled={saving} onClick={()=>void changeJob(job,"cancel")}>Cancelar</button>}{(job.status==="FAILED"||job.status==="CANCELLED")&&<button className="button secondary" disabled={saving} onClick={()=>void changeJob(job,"retry")}>Reintentar</button>}</div>)}</article>}
    <article className="detail-card comments-panel" id="source-evidence"><div className="comments-header"><div><span className="eyebrow">COMENTARIOS</span><h2>Evidencia original</h2></div><label className="search-field"><span className="sr-only">Buscar comentarios</span><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Buscar por texto o autor…"/></label></div><div className="button-row"><label>Fuente<select value={sourceFilter} onChange={event=>setSourceFilter(event.target.value)}><option value="">Todas las fuentes</option>{sources.map(source=><option key={source.id} value={source.id}>{source.title}</option>)}</select></label><label>Uso en análisis<select value={analysisFilter} onChange={event=>setAnalysisFilter(event.target.value)}><option value="all">Todos los comentarios</option><option value="included">Elegibles e incluidos</option><option value="excluded">Fuera del análisis</option></select></label></div>{loaded&&<p className="form-hint">{comments.filter(isAnalyzable).length.toLocaleString("es")} comentarios elegibles en fuentes listas e incluidas. La elegibilidad técnica no acredita relevancia ni aprobación editorial.</p>}{!loaded?<p role="status">{error?"No se pudo cargar la evidencia. Usa Reintentar.":"Cargando fuentes y comentarios…"}</p>:filtered.length===0?<div className="compact-empty">No hay comentarios que coincidan.</div>:<><div className="comment-list">{visibleComments.map((comment)=><article id={`comment-${comment.id}`} className={focusCommentId===comment.id?"evidence-focused":""} key={comment.id}><header><strong>{comment.author}</strong><div>{comment.isDemo&&<span className="demo-badge">DEMO</span>}<span>♥ {comment.likes}</span>{comment.isReply&&<span>Respuesta</span>}</div></header><p>{comment.text}</p><small>{sourceById.get(comment.sourceId)?.title??"Fuente no disponible"} · {isAnalyzable(comment)?"Elegible para análisis":!comment.analysisEligible?`Fuera del análisis: ${comment.noiseReason??"baja calidad"}`:"Fuente excluida o no lista"}</small><footer>{comment.publishedAt?new Date(comment.publishedAt).toLocaleString("es"):"Fecha no disponible"}</footer></article>)}</div><div className="comments-pagination" aria-live="polite"><span>Mostrando {visibleComments.length.toLocaleString("es")} de {filtered.length.toLocaleString("es")} comentarios</span>{remainingCommentCount>0&&<button type="button" className="button secondary" onClick={()=>setVisibleCommentCount(current=>current+COMMENT_RENDER_BATCH)}>Mostrar {Math.min(COMMENT_RENDER_BATCH,remainingCommentCount)} más</button>}</div></>}</article>
  </section>;
}

export function HistoryView({projectId}:{projectId:string}) {
  const [jobs,setJobs]=useState<Job[]>([]),[generations,setGenerations]=useState<Generation[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState<string|null>(null);
  const [knowledgeUsed,setKnowledgeUsed]=useState<import("../../api/client").KnowledgeUsed|null>(null);
  useEffect(()=>{setLoading(true);Promise.all([api.jobs(projectId),api.generations(projectId)]).then(([jobList,generationList])=>{setJobs(jobList.jobs);setGenerations(generationList.generations);}).catch((reason)=>setError(messageOf(reason))).finally(()=>setLoading(false));},[projectId]);
  if(loading)return <section className="content-section"><LoadingCards/></section>;
  const items:GenerationHistoryItem[]=generations.map((generation)=>({id:generation.id,projectId:generation.projectId,projectName:"Proyecto actual",moduleName:humanize(generation.agentKey),provider:generation.provider,model:generation.model,status:normalizeGenerationStatus(generation.status),createdAt:generation.createdAt,inputTokens:generation.inputTokens,outputTokens:generation.outputTokens,estimatedCost:generation.estimatedCost,durationMs:generation.durationMs,...(generation.versionNumber===null?{}:{versionNumber:generation.versionNumber}),result:historyResult(generation.outputData,generation.agentKey)}));
  const knowledgePanel=<article className="detail-card jobs-panel"><span className="eyebrow">KNOWLEDGE USED</span><div className="history-list">{generations.slice(0,8).map(generation=><div key={generation.id}><div><strong>{humanize(generation.agentKey)} · {new Date(generation.createdAt).toLocaleString("es")}</strong><button className="button secondary" onClick={()=>void api.knowledgeUsed(projectId,generation.id).then(setKnowledgeUsed).catch(reason=>setError(messageOf(reason)))}>Ver fuentes</button></div></div>)}</div>{knowledgeUsed&&<div className="knowledge-used-panel"><p><strong>Consulta:</strong> {knowledgeUsed.query} · {knowledgeUsed.contextTokenEstimate} tokens estimados</p>{knowledgeUsed.items.map(item=><article key={item.rank}><strong>[K{item.rank}] {item.title}</strong><small>{item.kind==="APPROVED_MEMORY"?"MEMORIA APROBADA":item.kind==="GLOBAL_KNOWLEDGE"?"KNOWLEDGE GLOBAL":"KNOWLEDGE DEL PROYECTO"} · {item.libraryName}{item.pageNumber?` · pág. ${item.pageNumber}`:""}</small><p>{item.content}</p></article>)}</div>}</article>;
  return <section className="content-section">{error&&<InlineError message={error}/>}<AnalyticsHistory generations={items} demoMode={generations.length>0&&generations.every((item)=>item.provider==="mock")}/>{knowledgePanel}<article className="detail-card jobs-panel"><span className="eyebrow">JOBS DE IMPORTACIÓN</span><div className="history-list">{jobs.length===0?<p>No hay jobs todavía.</p>:jobs.map((job)=><div key={job.id}><div><strong>{humanize(job.jobType)}</strong><span className={`status-pill ${job.status.toLowerCase()}`}>{job.status}</span></div><p>{job.message??"Sin mensaje"}</p><small>{job.progress}% · {new Date(job.createdAt).toLocaleString("es")}</small></div>)}</div></article></section>;
}

function StructuredOutput({value,evidence}:{value:unknown;evidence?:EvidenceSnippet[]|undefined}) {
  if(!isRecord(value))return <p className="muted-copy">El módulo no devolvió campos presentables.</p>;
  const entries=Object.entries(value).filter(([,item])=>item!==null&&item!==undefined&&item!=="");
  return <div className="structured-output">{entries.map(([key,item])=><StructuredField key={key} name={key} value={item} evidence={evidence}/>)}</div>;
}

function StructuredField({name,value,evidence}:{name:string;value:unknown;evidence?:EvidenceSnippet[]|undefined}):ReactNode {
  const label=FIELD_LABELS[name]??humanize(name);
  if(name==="schemaVersion")return <span className="meta-chip">Schema v{String(value)}</span>;
  if(name==="summary"&&typeof value==="string")return <section className="output-section output-summary"><p className="research-summary">{value}</p></section>;
  if(name==="subniches"&&Array.isArray(value)&&value.every((v)=>typeof v==="string"))return <section className="output-section"><h3>{label}</h3><div className="subniche-grid">{value.map((chip,index)=><div className="subniche-card" key={`${name}-${index}`}><span className="subniche-index">{String(index+1).padStart(2,"0")}</span><span className="subniche-name">{chip}</span></div>)}</div></section>;
  if(name==="searchSuggestions"&&Array.isArray(value)&&value.every((v)=>typeof v==="string"))return <section className="output-section"><h3>{label}</h3><div className="suggestion-list">{value.map((chip,index)=><div className="suggestion-row" key={`${name}-${index}`}><Search size={14} strokeWidth={1.8} className="suggestion-icon"/><span>{chip}</span></div>)}</div></section>;
  if(name==="questions"&&Array.isArray(value)&&value.every((v)=>typeof v==="string"))return <section className="output-section"><h3>{label}</h3><ol className="numbered-list">{value.map((q,index)=><li key={`${name}-${index}`}>{q}</li>)}</ol></section>;
  if((name==="hypotheses"||name==="insights")&&Array.isArray(value))return <section className="output-section"><h3>{label}</h3><div className={`finding-list ${name==="insights"?"perspectives-list":"hypotheses-list"}`}>{value.map((item,index)=><FindingItem key={`${name}-${index}`} item={item} index={index} evidence={evidence}/>)}</div></section>;
  if(name==="validationAudit"&&isRecord(value)){const ok=value.ok===true;const errors=Array.isArray(value.errors)?value.errors.filter((error):error is string=>typeof error==="string"):[];return <section className="output-section"><h3>{label}</h3><span className={`meta-chip ${ok?"meta-ok":"meta-warn"}`}>{ok?"Contrato y referencias válidos":"Requiere corrección"}</span>{typeof value.inputEvidenceCount==="number"&&<p>{value.inputEvidenceCount} evidencias consideradas · {String(value.citedEvidenceCount??0)} citadas</p>}{typeof value.unresolvedEvidenceRefs==="number"&&value.unresolvedEvidenceRefs>0&&<p>{value.unresolvedEvidenceRefs} referencias descartadas por no pertenecer a la muestra.</p>}{errors.length>0&&<details open><summary>Motivos de validación ({errors.length})</summary><ul>{errors.map((error,index)=><li key={index}>{error}</li>)}</ul></details>}<p className="form-hint">La validación del contrato y las referencias no confirma la veracidad de las hipótesis.</p></section>;}

  if(Array.isArray(value))return <section className="output-section"><h3>{label}</h3>{value.length===0?<p className="muted-copy">Sin elementos.</p>:<div className="output-list">{value.map((item,index)=><div className="output-item" key={`${name}-${index}`}>{isRecord(item)?Object.entries(item).map(([childKey,childValue])=><StructuredField key={childKey} name={childKey} value={childValue}/>):<PrimitiveValue value={item}/>}</div>)}</div>}</section>;
  if(isRecord(value))return <section className="output-section"><h3>{label}</h3><div className="output-object">{Object.entries(value).map(([childKey,childValue])=><StructuredField key={childKey} name={childKey} value={childValue}/>)}</div></section>;
  return <div className="output-field"><span>{label}</span><PrimitiveValue value={value}/></div>;
}

function FindingItem({item,index,evidence}:{item:unknown;index:number;evidence?:EvidenceSnippet[]|undefined}):ReactNode {
  const rec=isRecord(item)?item:{};
  const text=typeof rec.text==="string"?rec.text:"";
  const provenance=typeof rec.provenance==="string"?rec.provenance.trim().toUpperCase():"";
  const ids=Array.isArray(rec.evidenceIds)?rec.evidenceIds.filter((v):v is string=>typeof v==="string"):[];
  const provenanceLabel=provenance==="EVIDENCE_BACKED"?"Con evidencia":provenance==="AI_INFERENCE"?"Inferencia IA":provenance?humanize(provenance):"Sin clasificar";
  const tone=provenance==="EVIDENCE_BACKED"?"evidence-backed":provenance==="AI_INFERENCE"?"ai-inference":"unclassified";
  return <div className={`finding-item ${tone}`}>
    <span className="finding-index">{String(index+1).padStart(2,"0")}</span>
    <div className="finding-body">
      <p className="finding-text">{text}</p>
      <div className="finding-meta"><span className="provenance-tag">{provenanceLabel}</span>{ids.length>0?<span className="evidence-count">{ids.length} evidencia{ids.length>1?"s":""}</span>:<span className="evidence-none">Sin evidencia vinculada</span>}</div>
      {evidence&&ids.length>0&&<details><summary>Ver citas ({ids.length})</summary>{ids.map(id=>{const citation=evidence.find(item=>item.id===id);return citation?<blockquote key={id}><p>“{citation.quoteText}”</p><footer>{citation.author} · {citation.sourceTitle}</footer></blockquote>:<p key={id}>Referencia no disponible en el corpus actual: {id}</p>;})}</details>}
    </div>
  </div>;
}

function PrimitiveValue({value}:{value:unknown}) {
  if(typeof value==="boolean")return <strong>{value?"Sí":"No"}</strong>;
  if(typeof value==="number")return <strong>{value.toLocaleString("es")}</strong>;
  const text=String(value);
  const evidence=/evidence|comment|source/i.test(text)?" evidence-ref":"";
  return <p className={`field-value${evidence}`}>{text}</p>;
}

function DependencyEmpty({moduleKey,onRun,running}:{moduleKey:ModuleKey;onRun:()=>void;running:boolean}) {return <div className="empty-state large"><div className="empty-icon">{moduleInfo(moduleKey).short}</div><span className="phase-badge">Modo Demo disponible</span><h2>Aún no hay resultados</h2><p>El backend validará dependencias. Si faltan datos anteriores, mostrará la causa sin perder tu trabajo.</p><button className="button primary" disabled={running} onClick={onRun}>{running?"Generando…":"Generar borrador Demo"}</button></div>;}
function InlineError({message,onRetry}:{message:string;onRetry?:()=>void}) {return <div className="error-banner inline" role="alert"><div><strong>No se pudo completar la operación</strong><span>{message}</span></div>{onRetry&&<button className="button secondary" onClick={onRetry}>Reintentar</button>}</div>;}
function LoadingCards(){return <div className="loading-grid" aria-label="Cargando"><div/><div/><div/></div>;}
function isRecord(value:unknown):value is Record<string,unknown>{return typeof value==="object"&&value!==null&&!Array.isArray(value);}
function humanize(value:string){return value.replace(/([a-z])([A-Z])/g,"$1 $2").replaceAll("_"," ").replace(/\b\w/g,(letter)=>letter.toUpperCase());}
const FIELD_LABELS:Record<string,string>={summary:"Resumen",subniches:"Subnichos",hypotheses:"Hipótesis",questions:"Preguntas",searchSuggestions:"Sugerencias de búsqueda",insights:"Perspectivas",validationAudit:"Auditoría de validación",evidenceIds:"IDs de evidencia"};
function providerLabel(info?:{provider:string;model:string}|undefined):string{if(!info)return"Desconocido";const p=info.provider.toLowerCase();return p==="mock"?"Mock":p==="openai"?"OpenAI":p==="gemini"?"Gemini":p==="deepseek"?"DeepSeek":info.provider;}
function providerDotClass(info?:{provider:string;model:string}|undefined):string{const p=(info?.provider??"").toLowerCase();if(p==="gemini")return"provider-gemini";if(p==="deepseek")return"provider-deepseek";if(p==="mock")return"provider-mock";if(p==="openai")return"provider-openai";return"provider-unknown";}
function messageOf(reason:unknown){return reason instanceof Error?reason.message:"Ocurrió un error inesperado.";}
export function collectEvidenceIds(value:unknown):string[]{
  const found=new Set<string>();
  const add=(id:unknown)=>{if(typeof id==="string"&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id))found.add(id);};
  const visit=(item:unknown)=>{
    if(Array.isArray(item))item.forEach(visit);
    else if(isRecord(item))for(const [key,child] of Object.entries(item)){
      if(key==="analysisAudit"||key==="validationAudit")continue;
      if(key==="evidenceIds"&&Array.isArray(child))child.forEach(add);
      else if(key==="evidenceId")add(child);
      else if(typeof child==="object"&&child!==null)visit(child);
    }
  };
  visit(value);return [...found];
}
async function loadAllComments(projectId:string){const comments:Comment[]=[];for(let offset=0;;offset+=1000){const page=await api.comments(projectId,offset);comments.push(...page.comments);if(page.comments.length<1000)break;}return comments;}
function normalizeGenerationStatus(value:string):GenerationHistoryItem["status"]{return value==="FAILED"||value==="RUNNING"||value==="CANCELLED"?value:"COMPLETED";}
function historyResult(value:unknown,agentKey:string):NonNullable<GenerationHistoryItem["result"]>{if(!isRecord(value))return{title:humanize(agentKey),summary:"Resultado estructurado guardado.",fields:[]};const fields=Object.entries(value).slice(0,8).map(([key,item])=>({label:humanize(key),value:previewValue(item)}));return{title:humanize(agentKey),summary:`${fields.length} campos estructurados en esta generación.`,fields};}
function previewValue(value:unknown):string{if(Array.isArray(value))return `${value.length} elementos`;if(isRecord(value))return Object.keys(value).slice(0,5).map(humanize).join(", ")||"Objeto vacío";if(value===null||value===undefined)return"—";return String(value).slice(0,240);}
